import React from "react";

const PersonTable = ({ items = [], deletePerson }) => {
    if (!Array.isArray(items)) {
        console.error("PersonTable očekává pole, ale dostalo:", items);
        return <p>Chyba při načítání dat.</p>;
    }

    return (
        <table className="table">
            <thead>
                <tr>
                    <th>ID</th>
                    <th>Jméno</th>
                    <th>Akce</th>
                </tr>
            </thead>
            <tbody>
                {items.map((person) => (
                    <tr key={person._id}>
                        <td>{person._id}</td>
                        <td>{person.name}</td>
                        <td>
                            <button className="btn btn-danger" onClick={() => deletePerson(person._id)}>
                                Smazat
                            </button>
                        </td>
                    </tr>
                ))}
            </tbody>
        </table>
    );
};

export default PersonTable;
